import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { Category, Item, Trip, SharedPayload } from "@/types";

const STORAGE_KEY = "packwell-store";

function uid(prefix = "id"): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 7)}`;
}

function defaultCategories(): Category[] {
  return [
    { id: uid("cat"), name: "证件财物", icon: "Wallet", order: 0 },
    { id: uid("cat"), name: "衣物", icon: "Shirt", order: 1 },
    { id: uid("cat"), name: "洗漱护理", icon: "Droplets", order: 2 },
    { id: uid("cat"), name: "电子设备", icon: "Plug", order: 3 },
    { id: uid("cat"), name: "药品急救", icon: "Pill", order: 4 },
    { id: uid("cat"), name: "其他", icon: "Package", order: 5 },
  ];
}

function emptyTrip(title = "我的旅行清单"): Trip {
  const now = Date.now();
  return {
    id: uid("trip"),
    title,
    createdAt: now,
    updatedAt: now,
    categories: defaultCategories(),
    items: [],
  };
}

function exampleTrip(): Trip {
  const now = Date.now();
  const cats = defaultCategories();
  const items: Item[] = [
    { id: uid("i"), categoryId: cats[0].id, name: "护照 / 身份证", quantity: 1, note: "有效期6个月以上", packed: false, order: 0 },
    { id: uid("i"), categoryId: cats[0].id, name: "现金", quantity: 1, note: "小额零钱备用", packed: false, order: 1 },
    { id: uid("i"), categoryId: cats[0].id, name: "银行卡", quantity: 2, note: "", packed: false, order: 2 },
    { id: uid("i"), categoryId: cats[1].id, name: "内衣", quantity: 7, note: "", packed: false, order: 0 },
    { id: uid("i"), categoryId: cats[1].id, name: "袜子", quantity: 7, note: "", packed: false, order: 1 },
    { id: uid("i"), categoryId: cats[1].id, name: "外套", quantity: 1, note: "防风款", packed: false, order: 2 },
    { id: uid("i"), categoryId: cats[2].id, name: "牙刷 / 牙膏", quantity: 1, note: "", packed: false, order: 0 },
    { id: uid("i"), categoryId: cats[2].id, name: "洗面奶", quantity: 1, note: "分装≤100ml", packed: false, order: 1 },
    { id: uid("i"), categoryId: cats[3].id, name: "充电宝", quantity: 1, note: "≤100Wh可登机", packed: false, order: 0 },
    { id: uid("i"), categoryId: cats[3].id, name: "充电线", quantity: 2, note: "Type-C + Lightning", packed: false, order: 1 },
    { id: uid("i"), categoryId: cats[4].id, name: "常备药", quantity: 1, note: "感冒药 / 肠胃药", packed: false, order: 0 },
    { id: uid("i"), categoryId: cats[4].id, name: "创可贴", quantity: 10, note: "", packed: false, order: 1 },
  ];
  return {
    id: uid("trip"),
    title: "京都七日行",
    createdAt: now,
    updatedAt: now,
    categories: cats,
    items,
  };
}

function touch(trip: Trip): Trip {
  return { ...trip, updatedAt: Date.now() };
}

/** 从 SharedPayload 或 BackupFile.trip 创建新 Trip（重新生成所有 ID） */
function importTrip(data: { title: string; categories: Category[]; items: Item[] }): Trip {
  const now = Date.now();
  // 生成分类 ID 映射
  const catIdMap: Record<string, string> = {};
  const categories = data.categories.map((c) => {
    const newId = uid("cat");
    catIdMap[c.id] = newId;
    return { ...c, id: newId };
  });
  const items = data.items.map((it, idx) => ({
    ...it,
    id: uid("i"),
    categoryId: catIdMap[it.categoryId] ?? it.categoryId,
    packed: false, // 导入时重置打包状态
    order: idx,
  }));
  return {
    id: uid("trip"),
    title: data.title,
    createdAt: now,
    updatedAt: now,
    categories,
    items,
  };
}

interface PackState {
  trips: Trip[];
  currentTripId: string | null;
  initialized: boolean;
  personPresets: string[];
  locationPresets: string[];

  // 当前清单快捷访问
  currentTrip: () => Trip | null;

  // 清单管理
  initIfEmpty: () => void;
  createTrip: (title?: string) => string;
  createExampleTrip: () => string;
  switchTrip: (id: string) => void;
  renameTrip: (id: string, title: string) => void;
  duplicateTrip: (id: string, newTitle?: string) => string;
  deleteTrip: (id: string) => void;
  importFromPayload: (data: SharedPayload) => string;
  importFromBackup: (data: { title: string; categories: Category[]; items: Item[] }) => string;

  // 预设管理
  addPersonPreset: (name: string) => void;
  removePersonPreset: (name: string) => void;
  addLocationPreset: (name: string) => void;
  removeLocationPreset: (name: string) => void;

  // 当前清单内操作
  setTitle: (title: string) => void;
  clearItems: () => void;
  addItem: (data: Omit<Item, "id" | "order" | "packed">) => void;
  addItems: (items: Array<Omit<Item, "id" | "order" | "packed">>) => void;
  updateItem: (id: string, patch: Partial<Omit<Item, "id">>) => void;
  removeItem: (id: string) => void;
  togglePacked: (id: string) => void;
  addCategory: (name: string, icon: string) => void;
  updateCategory: (id: string, patch: Partial<Omit<Category, "id">>) => void;
  removeCategory: (id: string) => void;
  moveCategory: (id: string, direction: -1 | 1) => void;
}

export const usePackStore = create<PackState>()(
  persist(
    (set, get) => ({
      trips: [],
      currentTripId: null,
      initialized: false,
      personPresets: ["爸爸", "妈妈", "宝贝"],
      locationPresets: ["随身背包", "行李箱", "手提袋"],

      currentTrip: () => {
        const s = get();
        return s.trips.find((t) => t.id === s.currentTripId) ?? null;
      },

      initIfEmpty: () => {
        const s = get();
        if (!s.initialized || s.trips.length === 0) {
          const trip = exampleTrip();
          set({ trips: [trip], currentTripId: trip.id, initialized: true });
        }
      },

      createTrip: (title) => {
        const trip = emptyTrip(title);
        set((s) => ({
          trips: [...s.trips, trip],
          currentTripId: trip.id,
        }));
        return trip.id;
      },

      createExampleTrip: () => {
        const trip = exampleTrip();
        set((s) => ({
          trips: [...s.trips, trip],
          currentTripId: trip.id,
        }));
        return trip.id;
      },

      switchTrip: (id) => {
        set({ currentTripId: id });
      },

      renameTrip: (id, title) => {
        set((s) => ({
          trips: s.trips.map((t) =>
            t.id === id ? touch({ ...t, title }) : t
          ),
        }));
      },

      duplicateTrip: (id, newTitle) => {
        const s = get();
        const source = s.trips.find((t) => t.id === id);
        if (!source) return "";
        const dup = importTrip({ title: newTitle ?? `${source.title}（副本）`, categories: source.categories, items: source.items });
        set((s2) => ({
          trips: [...s2.trips, dup],
          currentTripId: dup.id,
        }));
        return dup.id;
      },

      deleteTrip: (id) => {
        set((s) => {
          const remaining = s.trips.filter((t) => t.id !== id);
          if (remaining.length === 0) {
            const fresh = emptyTrip();
            return { trips: [fresh], currentTripId: fresh.id };
          }
          return {
            trips: remaining,
            currentTripId: s.currentTripId === id ? remaining[0].id : s.currentTripId,
          };
        });
      },

      importFromPayload: (data) => {
        const trip = importTrip(data);
        set((s) => ({
          trips: [...s.trips, trip],
          currentTripId: trip.id,
        }));
        return trip.id;
      },

      importFromBackup: (data) => {
        const trip = importTrip(data);
        set((s) => ({
          trips: [...s.trips, trip],
          currentTripId: trip.id,
        }));
        return trip.id;
      },

      // ---- 当前清单内操作 ----

      setTitle: (title) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trips = [...s.trips];
          trips[idx] = touch({ ...trips[idx], title });
          return { trips };
        }),

      clearItems: () =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trips = [...s.trips];
          trips[idx] = touch({ ...trips[idx], items: [] });
          return { trips };
        }),

      addItem: (data) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const order =
            trip.items
              .filter((i) => i.categoryId === data.categoryId)
              .reduce((m, i) => Math.max(m, i.order), -1) + 1;
          const item: Item = { id: uid("i"), order, packed: false, ...data };
          const trips = [...s.trips];
          trips[idx] = touch({ ...trip, items: [...trip.items, item] });
          return { trips };
        }),

      addItems: (items) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const newItems: Item[] = [];
          items.forEach((data) => {
            const order =
              trip.items
                .filter((i) => i.categoryId === data.categoryId)
                .reduce((m, i) => Math.max(m, i.order), -1) + newItems.filter((i) => i.categoryId === data.categoryId).length + 1;
            newItems.push({ id: uid("i"), order, packed: false, ...data });
          });
          const trips = [...s.trips];
          trips[idx] = touch({ ...trip, items: [...trip.items, ...newItems] });
          return { trips };
        }),

      updateItem: (id, patch) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const trips = [...s.trips];
          trips[idx] = touch({
            ...trip,
            items: trip.items.map((i) => (i.id === id ? { ...i, ...patch } : i)),
          });
          return { trips };
        }),

      removeItem: (id) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const trips = [...s.trips];
          trips[idx] = touch({ ...trip, items: trip.items.filter((i) => i.id !== id) });
          return { trips };
        }),

      togglePacked: (id) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const trips = [...s.trips];
          trips[idx] = touch({
            ...trip,
            items: trip.items.map((i) =>
              i.id === id ? { ...i, packed: !i.packed } : i
            ),
          });
          return { trips };
        }),

      addCategory: (name, icon) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const order = trip.categories.reduce((m, c) => Math.max(m, c.order), -1) + 1;
          const cat: Category = { id: uid("cat"), name, icon, order };
          const trips = [...s.trips];
          trips[idx] = touch({ ...trip, categories: [...trip.categories, cat] });
          return { trips };
        }),

      updateCategory: (id, patch) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const trips = [...s.trips];
          trips[idx] = touch({
            ...trip,
            categories: trip.categories.map((c) =>
              c.id === id ? { ...c, ...patch } : c
            ),
          });
          return { trips };
        }),

      removeCategory: (id) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const trips = [...s.trips];
          trips[idx] = touch({
            ...trip,
            categories: trip.categories
              .filter((c) => c.id !== id)
              .map((c, i) => ({ ...c, order: i })),
            items: trip.items.filter((i) => i.categoryId !== id),
          });
          return { trips };
        }),

      moveCategory: (id, direction) =>
        set((s) => {
          const idx = s.trips.findIndex((t) => t.id === s.currentTripId);
          if (idx === -1) return s;
          const trip = s.trips[idx];
          const sorted = [...trip.categories].sort((a, b) => a.order - b.order);
          const ci = sorted.findIndex((c) => c.id === id);
          if (ci === -1) return s;
          const target = ci + direction;
          if (target < 0 || target >= sorted.length) return s;
          [sorted[ci], sorted[target]] = [sorted[target], sorted[ci]];
          const reindexed = sorted.map((c, i) => ({ ...c, order: i }));
          const trips = [...s.trips];
          trips[idx] = touch({ ...trip, categories: reindexed });
          return { trips };
        }),

      // ---- 预设管理 ----
      addPersonPreset: (name) =>
        set((s) => {
          const trimmed = name.trim();
          if (!trimmed || s.personPresets.includes(trimmed)) return s;
          return { personPresets: [...s.personPresets, trimmed] };
        }),
      removePersonPreset: (name) =>
        set((s) => ({
          personPresets: s.personPresets.filter((p) => p !== name),
        })),
      addLocationPreset: (name) =>
        set((s) => {
          const trimmed = name.trim();
          if (!trimmed || s.locationPresets.includes(trimmed)) return s;
          return { locationPresets: [...s.locationPresets, trimmed] };
        }),
      removeLocationPreset: (name) =>
        set((s) => ({
          locationPresets: s.locationPresets.filter((l) => l !== name),
        })),
    }),
    {
      name: STORAGE_KEY,
      partialize: (s) => ({
        trips: s.trips,
        currentTripId: s.currentTripId,
        initialized: s.initialized,
        personPresets: s.personPresets,
        locationPresets: s.locationPresets,
      }),
    }
  )
);
