import { useEffect, useRef, useState } from "react";
import { Check, Pencil } from "lucide-react";
import { usePackStore } from "@/store/usePackStore";
import { computeProgress } from "@/lib/progress";
import type { Trip } from "@/types";

interface ProgressHeaderProps {
  trip: Trip;
}

export function ProgressHeader({ trip }: ProgressHeaderProps) {
  const setTitle = usePackStore((s) => s.setTitle);
  const progress = computeProgress(trip.items);

  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(trip.title);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editing) {
      setDraft(trip.title);
      inputRef.current?.focus();
      inputRef.current?.select();
    }
  }, [editing, trip.title]);

  const commit = () => {
    const trimmed = draft.trim();
    if (trimmed && trimmed !== trip.title) {
      setTitle(trimmed);
    }
    setEditing(false);
  };

  const allDone = progress.total > 0 && progress.packed === progress.total;

  return (
    <header className="paper-card relative overflow-hidden p-5 sm:p-6">
      <div className="pointer-events-none absolute -right-6 -top-6 select-none">
        <div className="rounded-full border-2 border-dashed border-lavender/40 px-3 py-3 text-center opacity-70">
          <div className="font-mono text-[9px] uppercase tracking-widest text-lavender-deep">
            Packwell
          </div>
          <div className="font-display text-base leading-none text-lavender-deep">
            ✈
          </div>
        </div>
      </div>

      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <p className="mb-1 font-mono text-[11px] uppercase tracking-widest text-ink-soft">
            旅行清单
          </p>
          {editing ? (
            <input
              ref={inputRef}
              className="font-display text-2xl sm:text-3xl text-ink bg-transparent border-b border-dashed border-moss/50 focus:outline-none w-full"
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onBlur={commit}
              onKeyDown={(e) => {
                if (e.key === "Enter") commit();
                if (e.key === "Escape") setEditing(false);
              }}
            />
          ) : (
            <div className="flex items-center gap-2">
              <h1 className="font-display text-2xl sm:text-3xl text-ink leading-tight">
                {trip.title || "未命名旅行"}
              </h1>
              <button
                className="flex h-9 w-9 items-center justify-center rounded-tag text-ink-soft transition-colors hover:bg-sand-200/70 hover:text-ink"
                onClick={() => setEditing(true)}
                aria-label="编辑标题"
              >
                <Pencil size={16} />
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="mt-5">
        <div className="flex items-end justify-between">
          <div>
            <span className="font-mono text-3xl text-moss tabular-nums">
              {progress.percent}
            </span>
            <span className="font-mono text-sm text-ink-soft">%</span>
            <span className="ml-2 text-xs text-ink-soft">
              {progress.packed} / {progress.total} 件已打包
            </span>
          </div>
          {allDone && (
            <span className="stamp-tag animate-stamp-press">
              <Check size={13} /> 全部就绪
            </span>
          )}
        </div>
        <div className="mt-2 h-2.5 overflow-hidden rounded-full bg-sand-300/60">
          <div
            className="h-full rounded-full bg-gradient-to-r from-moss via-ochre to-teal transition-all duration-500"
            style={{ width: `${progress.percent}%` }}
          />
        </div>
      </div>
    </header>
  );
}
